import type { DomainPack, LlmClient, LlmRequest, ScanResult } from "../types";

export const EMPTY_SCAN: ScanResult = { summary: "", chunks: [], stats: {} };

/**
 * The "Interactive Demo Sandbox" provider.
 *
 * It implements the very same `LlmClient` contract as the remote providers, so
 * the pipeline, scoring, verification and reporting code paths are identical
 * with or without API keys. Output is generated by the pack's deterministic
 * analyzers, which means results are reproducible for judges and tests.
 */
export function createSandboxClient(pack: DomainPack): LlmClient {
  return {
    id: "sandbox",
    label: "Aegis Sandbox (deterministic)",
    mode: "sandbox",
    async complete(request: LlmRequest): Promise<string> {
      const input = request.context.input ?? "";
      const scan = request.context.scan ?? EMPTY_SCAN;

      switch (request.stage) {
        case "scanner":
          return JSON.stringify(pack.sandbox.scan(input));
        case "critic":
          return JSON.stringify(pack.sandbox.critique(input, scan));
        case "healer":
          return JSON.stringify(
            pack.sandbox.heal(
              input,
              scan,
              request.context.critique ?? { verdict: "", findings: [] },
              request.context.title,
            ),
          );
        case "verifier": {
          const checks = request.context.checks ?? [];
          const passed = checks.filter((check) => check.passed).length;
          return JSON.stringify({
            notes: [
              `Deterministic verifier: ${passed}/${checks.length} checks passed.`,
              "Sandbox mode validates against pack-specific rules and core invariants only.",
            ],
          });
        }
        default:
          return JSON.stringify({});
      }
    },
  };
}
